/// Decodes a Offset.
Offset? decodeOffset(Decoding d, Object? v) {
  final f = Fields.of(d, v);
  if (f == null) return null;
  return Offset(
    asDouble(d, f.get(1, 'dx')) ?? f.missing('dx'),
    asDouble(d, f.get(2, 'dy')) ?? f.missing('dy'),
  );
}

/// Decodes a RangeLabels.
RangeLabels? decodeRangeLabels(Decoding d, Object? v) {
