  );
}

/// Decodes a Shadow.
Shadow? decodeShadow(Decoding d, Object? v) {
  final f = Fields.of(d, v);
  if (f == null) return null;
  final o0 = asColor(d, f.get(1, 'color'));
  return o0 == null
      ? Shadow(
    offset: decodeOffset(d, f.get(2, 'offset')) ?? _default0,
    blurRadius: asDouble(d, f.get(3, 'blurRadius')) ?? 0.0,
  )
      : Shadow(
    color: o0,
    offset: decodeOffset(d, f.get(2, 'offset')) ?? _default0,
    blurRadius: asDouble(d, f.get(3, 'blurRadius')) ?? 0.0,
  );
}

/// Decodes a Size.
Size? decodeSize(Decoding d, Object? v) {
  final f = Fields.of(d, v);
