  return Size(
    asDouble(d, f.get(1, 'width')) ?? f.missing('width'),
    asDouble(d, f.get(2, 'height')) ?? f.missing('height'),
  );
}

/// Decodes a TextSpan.
TextSpan? decodeTextSpan(Decoding d, Object? v) {
  final f = Fields.of(d, v);
  if (f == null) return null;
  return TextSpan(
    text: asString(d, f.get(1, 'text')),
    children: listOfTextSpan(d, f.get(2, 'children')),
    style: decodeTextStyle(d, f.get(3, 'style')),
    semanticsLabel: asString(d, f.get(4, 'semanticsLabel')),
